% -------------------------------------------------------------------------
% PL Greenness Figure Reproduction Script
% -------------------------------------------------------------------------
% Recreates the manuscript figures for "Optimal light use strategy explains
% seasonal vegetation greenness dynamics and trends". The workflow contrasts
% PL-model greenness with satellite benchmarks, flux sites, and TRENDY
% ensembles. Run inside code/ with the packaged data/ assets available.
% -------------------------------------------------------------------------
% The script expects the data/ directory one level up to contain all GeoTIFF
% stacks and MAT files referenced below. Figure assets are written to figure/.
% -------------------------------------------------------------------------
% -------------------------------------------------------------------------
% Source Data Output (Nature Comms editorial transparency request)
% Save the raw data behind Figs. 1, 2, 3a, 4d, 6, and Appendix to an Excel
% workbook per figure, under ../source_data/. Each workbook contains one
% sheet that mirrors what is plotted in the corresponding figure panel.
% -------------------------------------------------------------------------
if ~exist('path_source_output','var')
    path_source_output = '../source_data/';
end
if ~isfolder(path_source_output)
    mkdir(path_source_output);
end
% Require Statistics Toolbox or R2016b-style writematrix
hasExcelWrite = exist('writematrix','file') == 2 || exist('writecell','file') == 2 || exist('xlswrite','file') == 2;
%%
%% Figure 1 – Global seasonality of greenness versus potential production
% Builds the three panel map comparing MODIS fAPAR and PL-derived A0
% seasonality plus the accompanying latitude band summary curve.
% Load the static mask and add helper utilities required by custom plotting
% and statistical routines used across all figures.
roi_single_year = geotiffread("../data/roi_global_05d.tif"); %#ok<*GTRED> 
addpath("./utility/");

% Shared plotting and analysis settings
timestep = 30;                    % Approximate number of days per composited step
font_size = 11;                   % Base font size for shared colorbars
options.fontsize = 14;            % Map annotation font size
options.text_position_middle = [-56,-46];
options.text_position_right = [-158,-46];

% Load monthly (MODIS, PL model, TRENDY) and weekly (A0) stacks used to
% summarize greenness and potential production.
fapar_obs_mon = geotiffread("../data/fapar_global_modis_05d.tif");
fapar_sim_mon = geotiffread("../data/fapar_global_plmodel_05d.tif");
raster_trendy_12mon = geotiffread("../data/fapar_trendy_plmodel_05d.tif");
A0_gC_weekly = geotiffread("../data/a0_global_plmodel_05d.tif");

% Collapse each stack into seasonality diagnostics using the shared TS()
% helper. Timing outputs are retained for completeness although not used
% directly in the figure panels.
[seasonalityA0,timingA0,timingA0Cos] = TS(A0_gC_weekly,'timestep',timestep);
[seasonalityPL,timingPL,timingPLCos] = TS(fapar_sim_mon,'timestep',timestep);
[seasonalityMod,timingMod,timingModCos] = TS(fapar_obs_mon,'timestep',timestep);
[seasonalityTrendy,timingTrendy,timingTrendyCos] = TS(raster_trendy_12mon,'timestep',timestep);

% Precompute color palettes and shared temporal metadata
cb_paired = cbrewer_hint("qual", "Paired", 12);
cb_set1 = cbrewer_hint("qual","Set1",9);
cb_set2 = cbrewer_hint("qual","Set2",8);
cb_pastel2 = cbrewer_hint('qual','Pastel2',9);

YearBgn = 2000;
YearEnd = 2019;
YearNum = numel(YearBgn:YearEnd);

options.range_value = [0, 0.9];
options.text_position = [-160,-45];
roi_12mon = repmat(roi_single_year, [1,1,12]);

% All figures export to the shared figure/ folder
path_figure_output = '../figure/';
%%
% Create the composite layout with two rows of maps and a shared side panel
fig = figure('Color', [1 1 1]); %[output:6aa322ae]
fig.Position(3) = fig.Position(3)*1.12; %[output:6aa322ae]
fig.Position(2) = fig.Position(2)*0.6; %[output:6aa322ae]
fig.Position(4) = fig.Position(4)*1.08; %[output:6aa322ae]

left_width = 10;
right_width = 4;
tl = tiledlayout(2,left_width + right_width,"TileSpacing","tight"); %[output:6aa322ae]
tl.Padding = "compact"; % Match legacy spacing so shared colorbars align with map width %[output:6aa322ae]

% Panel (a): MODIS fAPAR seasonality map
nexttile(1, [1,left_width]); %[output:6aa322ae]
data_obs = seasonalityMod;
data_obs(~(roi_single_year)) = nan;
geoshow_global(data_obs,"logic_show_yticks","true","logic_show_xticks","false"); %[output:6aa322ae]
set(gca, 'Clim', [0, 1.0]); %[output:6aa322ae]
set(gca,'FontSize',options.fontsize-3); %[output:6aa322ae]

% Panel (b): PL modeled A0 seasonality map
nexttile(1+(left_width+right_width), [1,left_width]); %[output:6aa322ae]
data_sim = seasonalityA0;
data_sim(~(roi_single_year)) = nan;
geoshow_global(data_sim,"logic_show_yticks","true","logic_show_xticks","false"); %[output:6aa322ae]
set(gca, 'Clim', [0, 1]); %[output:6aa322ae]
set(gca,'FontSize',options.fontsize-3); %[output:6aa322ae]

cb_map = slanCM(56, 12); colormap(cb_map(2:(end-1),:)); %[output:6aa322ae]
cb = colorbar(gca, 'Location', 'southoutside','FontSize',font_size);% cbarrow %[output:6aa322ae]
% cb.Layout.Tile = 'south';
% cb.Layout.TileSpan = [1 left_width]; % Keep bar centered beneath the paired map tiles

% Panel (c): Latitude band summary of both seasonality metrics
nexttile(1+left_width, [2,right_width]); %[output:6aa322ae]
[mean_lat_band, std_lat_band, ~] = plot_lat_bands(cat(3,data_obs,data_sim), "logic_plot",true, "ylabel",'',"fontsize",13,'fontbold','normal','str_legend',["\it{f}\rm_{APAR}","\it{A}\rm_{0}\rm"],'line_color',cb_paired([2,6],:)); %[output:6aa322ae]
set(gca,'FontSize',options.fontsize-3); %[output:6aa322ae]
yticks(0:0.4:1); %[output:6aa322ae]

% Export Figure 1 source data: latitude-band seasonality summary
n_lat = size(data_obs, 1);
lat_edges = linspace(-90, 90, n_lat + 1);
lat_centers = (lat_edges(1:end-1) + lat_edges(2:end)) / 2;
fig1_src = table(mean_lat_band(:,1), mean_lat_band(:,2), std_lat_band(:,1), std_lat_band(:,2), ...
    'VariableNames', {'fAPAR_Mean', 'A0_Mean', 'fAPAR_Std', 'A0_Std'});
writetable(fig1_src, fullfile(path_source_output, 'Fig1_source_data.xlsx'), ...
    'Sheet', 'LatBand_Seasonality');

exportgraphics(fig, fullfile(path_figure_output, 'Seasonality_Pattern_A0.png'),"Resolution",600); %[output:6aa322ae]
%%
%% Figure 2 – Flux site synchrony between fAPAR and potential production
% Visualizes how observed greenness co-varies with A0 across eddy covariance
% biomes using box and jittered scatter summaries, plus a map of correlation
% strength for the tower network.
param_table = readtable("../data/FluxInformation.csv"); %[output:89c6844d] %[output:8103a596]
fig_flux = figure('Color',[1 1 1]); %[output:7cf63013]
fig_flux.Position(4) = fig_flux.Position(4)*0.7; %[output:7cf63013]
colororder(fig_flux, cb_paired([2,1,6],:));
cb_violin = [cb_paired(2,:); cb_paired(1,:)];

% Order categories to match manuscript grouping
param_table_target = ["EBF","SAV","WSA","OSH","CSH","GRA","WET","ENF","MF","DBF"];
param_table.categorial = categorical(param_table.IGBPClass, param_table_target, param_table_target);

% Use a single tile layout to overlay box charts and jittered points
nexttile; %[output:7cf63013]
hold on; %[output:7cf63013]
index_grp = cat(1, repmat(categorical("P model"), height(param_table),1));
boxchart(repmat(param_table.categorial, [1,1]), [param_table.r_a0_fapar], 'GroupByColor',index_grp,"MarkerStyle","none","Notch","off","MarkerSize",12,"JitterOutliers","off"); %[output:7cf63013]
ylabel('\it{r}','FontSize',options.fontsize); %[output:7cf63013]
ylim([0,1]); %[output:7cf63013]
set(gca, 'fontsize', options.fontsize-2); %[output:7cf63013]
box on; %[output:7cf63013]
[found, idx] = ismember(param_table.categorial, categorical(param_table_target));
[~, sortorder] = sort(idx);
newT = param_table.categorial(sortorder,:);
scatter(newT,param_table.r_a0_fapar(sortorder,:),'filled','MarkerFaceAlpha',0.6,'jitter','on','jitterAmount',0.15); %[output:7cf63013]

if any(~found)
    error('Site not on approved list, first at row %d', find(~found,1));
end

nexttile; %[output:7cf63013]
% Overlay individual site correlations to show spread within each biome
violinplot(param_table.r_a0_fapar(sortorder,:), newT,'QuartileStyle','boxplot','ViolinColor',cb_violin(1,:),'MarkerSize',12,'ShowWhiskers',false,'ShowBox',true,'ViolinAlpha',0,'EdgeColor',cb_violin(2,:),'ShowData',false,'ShowMean',false); %[output:7cf63013]
ylabel('\it{r}','FontSize',options.fontsize); %[output:7cf63013]
hold off; %[output:7cf63013]
box on; %[output:7cf63013]
% grid on;
xlim([0.5, numel(param_table_target)+0.5]); %[output:7cf63013]
ylim([0, 1]); %[output:7cf63013]
set(gca, 'fontsize', options.fontsize-2); %[output:7cf63013]
% ---- Figure 2 source data: flux site synchrony box+jitter ----
fig2_src = param_table(:,'r_a0_fapar');                       % correlation coefficient
fig2_src.IGBPClass = categorical(param_table.categorial);     % biome grouping used in the figure
writetable(fig2_src, fullfile(path_source_output, 'Fig2_source_data.xlsx'), ...
    'Sheet', 'FluxSynchrony_Box', 'WriteMode', 'overwritesheet');
exportgraphics(fig_flux, fullfile(path_figure_output, 'FluxSynchrony_Box.png'),"Resolution",600); %[output:7cf63013]
% Companion map: spatial distribution of the site correlations
fig_flux_map = figure('Color',[1 1 1]); %[output:171d225d]
ax = geoaxes(fig_flux_map); %[output:171d225d]
ax.Scalebar.Visible = 'off'; %[output:171d225d]
geoscatter(double(param_table.Lat), double(param_table.Lon), 20, param_table.('r_a0_fapar'),"filled"); %[output:171d225d]
ax.LongitudeLabel.String = 'Longitude (°)'; %[output:171d225d]
ax.LatitudeLabel.String = 'Latitude (°)'; %[output:171d225d]
geolimits(ax,[-60, 70],[-175, 175]); %[output:171d225d]

ax.FontSize = options.fontsize-3; %[output:171d225d]
cb = colorbar('Location','southoutside','FontSize',font_size); %[output:171d225d]
colormap(cbrewer_hint("seq","GnBu",8)); %[output:171d225d]
ax.CLim = [0.1,0.9]; %[output:171d225d]
warning off;
cbarrow; %[output:171d225d]
warning on;
% ---- Figure 2 source data: flux site map ----
fig2_map_src = param_table(:,{'Lat','Lon','IGBPClass','r_a0_fapar'});
fig2_map_src.Lat = double(fig2_map_src.Lat);
fig2_map_src.Lon = double(fig2_map_src.Lon);
writetable(fig2_map_src, fullfile(path_source_output, 'Fig2_source_data.xlsx'), ...
    'Sheet', 'FluxSynchrony_Map', 'WriteMode', 'append');
geobasemap("grayland") %[output:171d225d]
exportgraphics(fig_flux_map, fullfile(path_figure_output, 'FluxSynchrony_Map.png'),"Resolution",600); %[output:171d225d]
%%
% Companion map: spatial distribution of the site correlations on a Köppen-style basemap
% Uses the same axesm/landareas.shp layout as the Köppen map so visual style is
% consistent across the manuscript. Site correlation values (r_a0_fapar) are
% mapped to marker colour rather than to Koppen class.
fig_flux_map_koppen = figure('Color',[1 1 1]); %[output:632f3252]
set(gca, 'FontSize', options.fontsize-2); %[output:632f3252]

land_path = fullfile(matlabroot, 'toolbox', 'map', 'mapdata', 'landareas.shp');
if ~isfile(land_path)
    warning('Landareas shapefile not found at %s. Sites plotted without land mask.', land_path);
    land_shapes = [];
else
    land_shapes = shaperead(land_path, 'UseGeoCoords', true);
end

ax_koppen = axesm('eqdcylin', 'Frame', 'off', 'Grid', 'off', ... %[output:632f3252]
    'MapLatLimit', [-70, 90], 'MapLonLimit', [-180, 180], ... %[output:632f3252]
    'MeridianLabel', 'off', 'ParallelLabel', 'off', ... %[output:632f3252]
    'MLabelParallel', 'south', 'PLineLocation', 45, 'MLineLocation', 30); %[output:632f3252]

setm(ax_koppen, 'FEdgeColor', [0.5, 0.5, 0.5], 'FLineWidth', 1.0); %[output:632f3252]
axis on %[output:632f3252]

if ~isempty(land_shapes)
    geoshow(ax_koppen, land_shapes, 'FaceColor', [0.93, 0.93, 0.93], 'EdgeColor', [0.7, 0.7, 0.7], 'LineWidth', 1.0); %[output:632f3252]
end

hold(ax_koppen, 'on'); %[output:632f3252]
site_lats = double(param_table.Lat);
site_lons = double(param_table.Lon);
site_r = param_table.('r_a0_fapar');
valid_site = isfinite(site_lats) & isfinite(site_lons) & isfinite(site_r);
scatterm(ax_koppen, site_lats(valid_site), site_lons(valid_site), ... %[output:632f3252]
    20, site_r(valid_site), 'filled', ... %[output:632f3252]
    'MarkerEdgeColor', [0.2, 0.2, 0.2], 'LineWidth', 0.4); %[output:632f3252]
tightmap %[output:632f3252]

colormap(cbrewer_hint("seq","GnBu",8)); %[output:632f3252]
caxis([0.1, 0.9]); %[output:632f3252]
cb_koppen = colorbar('Location','southoutside','FontSize',font_size); %[output:632f3252]
warning off;
cbarrow; %[output:632f3252]
warning on;
% ---- Figure 2 source data: flux site map (Köppen-style layout) ----
fig2_map_src_koppen = param_table(:,{'Lat','Lon','IGBPClass','r_a0_fapar'});
fig2_map_src_koppen.Lat = double(fig2_map_src_koppen.Lat);
fig2_map_src_koppen.Lon = double(fig2_map_src_koppen.Lon);
% writetable(fig2_map_src_koppen, fullfile(path_source_output, 'Fig2_source_data.xlsx'), ...
%     'Sheet', 'FluxSynchrony_Map_Koppen', 'WriteMode', 'append');
exportgraphics(fig_flux_map_koppen, fullfile(path_figure_output, 'FluxSynchrony_Map_Koppen.png'),"Resolution",600); %[output:632f3252]
%%
%% Figure 3 – Global multi year fAPAR comparison
% Provides the paired PL versus MODIS climatology maps and a latitude band
% comparison for the averaging period. A dedicated scatter plot follows in
% the supplementary panel.
fig = figure('Color', [1 1 1]); %[output:7a418deb]
fig.Position(3) = fig.Position(3)*1.1; %[output:7a418deb]
fig.Position(4) = fig.Position(4)*1.08; %[output:7a418deb]
tl_fig3 = tiledlayout(2,3,"TileSpacing","tight"); %[output:7a418deb]
tl_fig3.Padding = "compact"; % Preserve compact margins across MATLAB releases %[output:7a418deb]

% Panel (a): PL model climatology
nexttile(1, [1,2]); %[output:7a418deb]
fapar_predicted_min_matrix_disp = mean(fapar_sim_mon, 3, "omitnan");
fapar_predicted_min_matrix_disp(~roi_single_year) = nan;
geoshow_global(fapar_predicted_min_matrix_disp,"logic_show_yticks","true","logic_show_xticks","false"); %[output:7a418deb]
set(gca, 'Clim', options.range_value); %[output:7a418deb]
text(options.text_position_middle(1)+34, options.text_position_middle(2)-2, 'PL model','FontSize',options.fontsize); %[output:7a418deb]
set(gca,'FontSize',options.fontsize); %[output:7a418deb]

% Panel (b): MODIS climatology
nexttile(4, [1,2]); %[output:7a418deb]
data_disp = mean(fapar_obs_mon, 3, "omitnan");
data_disp(data_disp==0)=nan;
data_disp(~roi_single_year) = nan;
geoshow_global(data_disp,"logic_show_yticks","true","logic_show_xticks","false"); %[output:7a418deb]
set(gca, 'Clim', options.range_value); %[output:7a418deb]

cb = colorbar(gca, 'southoutside','FontSize',font_size);% cbarrow %[output:7a418deb]
% cb.Layout.Tile = 'south';
% cb.Layout.TileSpan = [1 2];
% cbarrow('right');
text(options.text_position_middle(1)+44, options.text_position_middle(2)-2, 'MODIS','FontSize',options.fontsize); %[output:7a418deb]
set(gca,'FontSize',options.fontsize); %[output:7a418deb]

cb_map = slanCM(56, 10); colormap(cb_map(1:(end-1),:)); %[output:7a418deb]

% Panel (c): Compare zonal means across products
nexttile(3, [2,1]); %[output:7a418deb]
plot_lat_bands(cat(3,fapar_predicted_min_matrix_disp, data_disp), "logic_plot",true, "ylabel",'',"fontsize",13,'fontbold','normal','str_legend',["PL model","MODIS"],'line_color',cb_set1(1:4,:)); %[output:7a418deb]
exportgraphics(fig, fullfile(path_figure_output, 'spatial_compare.png'),"Resolution",600); %[output:7a418deb]
%% Figure 3 – Pixel-wise density comparison (panel a)
% Uses a log density scatter to contrast monthly PL and MODIS fAPAR across
% all valid grid cells.
fig_density = figure('Color',[1 1 1]); %[output:12a4b9a1]
set(gca,'fontsize',options.fontsize-3); %[output:12a4b9a1]

roi_resample = logical(roi_12mon);
[mdl, X, Y] = scatter_plot_data_comparison(fapar_sim_mon(roi_resample), fapar_obs_mon(roi_resample), "PlotDisp","off","PlotDensity","on","PlotConf","off","AxisLim",[0,1.1,0,1.1],"AxisEqual","on","StatisLocation","northwest","StatisDispItem","r2+rmse+equ","StatisCrossZero","off", "RobustOpts","off","FontSize",options.fontsize-2); %[output:12a4b9a1]
xlabel('PL model Monthly \it{f}\rm_{APAR}') %[output:12a4b9a1]
ylabel('MODIS Monthly \it{f}\rm_{APAR}') %[output:12a4b9a1]
grid off; %[output:12a4b9a1]
set(gca,'ColorScale','log'); %[output:12a4b9a1]
set(gca,'fontsize',options.fontsize); %[output:12a4b9a1]
text(0.88, 0.7, "Density","FontSize",options.fontsize-1.5); %[output:12a4b9a1]
cb = colorbar(gca, 'eastoutside','Units','normalized','FontSize',font_size); %[output:12a4b9a1]
cb.Position = [0.65, 0.18, 0.02, 0.42]; %[output:12a4b9a1]
cb.Ticks = [10^-2, 10^-1, 1, 10]; %[output:12a4b9a1]
set(gca, 'clim', [cb.Ticks(1), cb.Ticks(end)]); %[output:12a4b9a1]
cb.TickLabels = {'1', '10', '100', '1000'}; %[output:12a4b9a1]
% ============================================================
% Figure 3a source data (pixel-wise density scatter, Nature Comms)
% ============================================================
roi_resample_fig3a = logical(roi_12mon);
pl_vals    = fapar_sim_mon(roi_resample_fig3a);
modis_vals = fapar_obs_mon(roi_resample_fig3a);
keep       = ~isnan(pl_vals) & ~isnan(modis_vals) & (pl_vals>1e-3) & (modis_vals>1e-3);
fig3a_src  = table(X, Y, ...
    'VariableNames', {'PL_model_monthly_fAPAR','MODIS_monthly_fAPAR'});
writetable(fig3a_src, fullfile(path_source_output, 'Fig3a_source_data.xlsx'), ...
    'Sheet', 'PixelDensityScatter');
% clear pl_vals modis_vals keep fig3a_src roi_resample_fig3a;
cb_map = slanCM(61, 30); cb_map = flipud(cb_map(1:(end-5),:)); colormap(cb_map); % classic color viridis %[output:12a4b9a1]
exportgraphics(fig_density, fullfile(path_figure_output, 'spatial_compare_density.png'),"Resolution",600); %[output:12a4b9a1]
%%
%% Figure 4 – Seasonal cycle comparison across MODIS, TRENDY, and PL
% Shows the spatial seasonality concentration for MODIS, TRENDY ensemble,
% and PL simulations in a vertical stack with matched color scaling.
xtext = -56;
ytext = -44;
sizetext = 13;

fig = figure('Color', [1 1 1]); %[output:7458a899]
fig.Position(3) = fig.Position(3)*0.7; %[output:7458a899]
fig.Position(2) = fig.Position(2)*0.6; %[output:7458a899]
fig.Position(4) = fig.Position(4)*1.2; %[output:7458a899]

tl_fig4 = tiledlayout(3,1,"TileSpacing","tight"); %[output:7458a899]
tl_fig4.Padding = "compact"; %[output:7458a899]

% Panel (a): TRENDY ensemble seasonality magnitude
nexttile(1, [1,1]); %[output:7458a899]
data_sim = seasonalityTrendy;
data_sim(~(roi_single_year)) = nan;
geoshow_global(data_sim,"logic_show_ticks","false"); %[output:7458a899]
set(gca, 'Clim', [0, 1]); %[output:7458a899]
text(xtext, ytext, ['TRENDY ', 'Seasonality'],'FontSize',sizetext); %[output:7458a899]
set(gca,'FontSize',options.fontsize); %[output:7458a899]

% Panel (b): MODIS benchmark seasonality magnitude
nexttile(2, [1,1]); %[output:7458a899]
data_obs = seasonalityMod;
data_obs(~(roi_single_year)) = nan;
geoshow_global(data_obs,"logic_show_ticks","false"); %[output:7458a899]
set(gca, 'Clim', [0, 1.0]); %[output:7458a899]
text(xtext, ytext, ['\it{f}\rm_{APAR} ', 'Seasonality'],'FontSize',sizetext); %[output:7458a899]
set(gca,'FontSize',options.fontsize); %[output:7458a899]

% Panel (c): PL model seasonality magnitude
nexttile(3, [1,1]); %[output:7458a899]
data_sim = seasonalityPL;
data_sim(~(roi_single_year)) = nan;
geoshow_global(data_sim,"logic_show_ticks","false"); %[output:7458a899]
set(gca, 'Clim', [0, 1]); %[output:7458a899]
text(xtext, ytext, ['PL model ', 'Seasonality'],'FontSize',sizetext); %[output:7458a899]
set(gca,'FontSize',options.fontsize); %[output:7458a899]

cb_map = slanCM(56, 12); colormap(cb_map(2:(end-1),:)); %[output:7458a899]
font_size = max(font_size, 13);

cb = colorbar(gca, 'southoutside','FontSize',font_size);% cbarrow %[output:7458a899]
cb.Layout.Tile = 'south'; %[output:7458a899]
% cb.Position(4) = cb.Position(4)*0.4;
% cbarrow('right');
exportgraphics(fig, fullfile(path_figure_output, 'Seasonality_Pattern.png'),"Resolution",600); %[output:7458a899]

load(fullfile('../data/', ['trendy_param_output','.mat']))
load(fullfile('../data/', ['trendy_data_output','.mat']))

num = size(param_model.name,1);
% show the comparison of the trendy models
param_model.name{num+1} = 'PLmodel';
param_model.r2_fit(num+1) = 0.81;
% param_model.r2_season(num+1) = 0.86;
param_model.rmse_fit(num+1) = 0.13;

[~, ind_sort] = sort(param_model.r2_fit, 1, "ascend");
X = categorical(param_model.name(ind_sort));
X = reordercats(X,param_model.name(ind_sort));

fig_trendy = figure('Color',[1 1 1]); %[output:18b783a8]
colororder(cat(1, [0.1,0.1,0.1], cb_set2(3,:)))

yyaxis left %[output:18b783a8]
