clear fig_line

% fig = plot(data_model.year(1,:), gpp_pg_annual_mean, "Color", [70,70,70]/255, 'LineStyle','-','LineWidth',2.4);

for num_disp = 1:(size(data_model.lai, 1)-1)
    fig_line(num_disp) = plot(data_model.year(1,:), data_model.lai(num_disp,:), "Color", cb_paired(num_disp,:), 'LineStyle','-','LineWidth',1.2); %[output:91779b62]
end
hold off; %[output:91779b62]
legend(fig_line, param_model.name, "Location", "eastoutside","Box","off"); %[output:94bb0e79] %[output:91779b62]

% box on;
% grid on;
xlabel('Year'); %[output:91779b62]
ylabel('Total GPP (PgC yr^{-1})'); %[output:91779b62]

% Export annual GPP of each model to Excel
fig_app_src = array2table([data_model.year(1,:).' , data_model.lai(1:(end-1),:).'], ...
    'VariableNames', [{'Year'}, cellstr(param_model.name(1:(end-1))).']);
writetable(fig_app_src, fullfile(path_source_output, 'FigS29_source_data.xlsx'), ...
    'Sheet', 'AnnualGPP_by_Model');

